<?php
declare(strict_types=1);
function cat_transition_scope(array $offer,string $stage,int $project):void{$scope=pricing_scope($project,true);$raw=ai_json($scope);crm_query('INSERT INTO nd_catalog_scope_transitions(offer_id,stage,from_hash,to_hash,scope_json) VALUES (?,?,?,?,?)',[$offer['id'],$stage,$offer['pricing_scope_hash'],hash('sha256',$raw),$raw]);}
function cat_current_offer(array $r,array $o,bool $expiry=true):array{
 $b=cat_brief($r);if((int)$b['id']!==(int)$o['brief_id']||!hash_equals($o['checksum'],hash('sha256',$o['body'])))crm_fail(409,'Редакция предложения больше не актуальна.');$latest=(int)crm_query('SELECT MAX(id) FROM nd_catalog_offers WHERE request_id=?',[$r['id']])->fetchColumn();if($latest!==(int)$o['id'])crm_fail(409,'Есть более новое предложение.');if($expiry&&$o['expires_at']<=gmdate('Y-m-d H:i:s'))crm_fail(409,'Срок предложения истёк. Запросите новое предложение.');$body=json_decode($o['body'],true);foreach([[(int)$body['spec_revision_id'],$body['spec_checksum']],[(int)$o['proposal_revision_id'],$body['proposal_checksum']]] as [$rid,$hash]){$rev=cc_revision(['type'=>'owner','id'=>1],$rid);if(!hash_equals($hash,$rev['checksum']))crm_fail(409,'Точная редакция документа изменилась.');$ids=array_map(fn($x)=>(int)$x['file_id'],crm_query('SELECT file_id FROM nd_cc_revision_files WHERE revision_id=?',[$rid])->fetchAll());cc_files_for(['type'=>'owner','id'=>1],(int)$r['project_id'],$ids,true);}$q=pricing_require_approved((int)$r['project_id']);if((int)$q['id']!==(int)$o['quotation_id']||!hash_equals($q['checksum'],$o['quotation_hash']))crm_fail(409,'NEEDS_COST_REVIEW: цена или исходные условия изменились.');return $q;
}
function cat_prepare_offer(int $id,array $d):array{
 return crm_idempotent('catalog:offer:'.$id,$d,function()use($id,$d){$a=['type'=>'owner','id'=>1];$r=cat_request($a,$id,true);crm_version($d,$r);if(!in_array($r['state'],['SUBMITTED','PRICING'],true))crm_fail(409,'Сначала отправьте актуальный бриф и рассчитайте цену.');$b=cat_brief($r);$q=pricing_require_approved((int)$r['project_id']);$spec=cc_revision($a,(int)$b['spec_revision_id']);if($spec['status']!=='draft')crm_fail(409,'Нужна новая редакция брифа и ТЗ.');$terms=cc_text($d,'terms',3000);$until=cc_text($d,'expires_at',19);$dt=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$until,new DateTimeZone('UTC'));if(!$dt||$dt->format('Y-m-d H:i:s')!==$until||$until<=gmdate('Y-m-d H:i:s')||$until>gmdate('Y-m-d H:i:s',time()+90*86400))crm_fail(422,'Укажите будущий срок предложения UTC, не более 90 дней.');$due=$d['due_on']??null;if($due!==null){if(!is_string($due))crm_fail(422,'Проверьте срок работ.');$date=DateTimeImmutable::createFromFormat('!Y-m-d',$due);if(!$date||$date->format('Y-m-d')!==$due||$due<gmdate('Y-m-d'))crm_fail(422,'Проверьте одобренный срок работ.');}
 $brief=json_decode($b['structured_json'],true);$text='Услуга: '.$brief['service']."\nПакет: ".$brief['package']['name']."\nОписание пакета: ".$brief['package']['description']."\nОбъём работ:\n".implode("\n",$brief['service_scope'])."\nСогласованная владельцем цена: ".bill_decimal((int)$q['calculation']['selling_minor'])." RUB.\nРезультаты:\n".implode("\n",$brief['service_deliverables'])."\nУсловия владельца:\n".$terms;
 $artifact=$d['ai_artifact_id']??null;if($artifact!==null){$x=crm_query("SELECT a.body,t.project_id,p.proposal_json,p.proposal_hash FROM nd_ai_artifacts a JOIN nd_ai_tasks t ON t.id=a.task_id JOIN nd_ai_approvals p ON p.artifact_id=a.id WHERE a.id=? AND t.agent_id='proposal'",[cc_id($artifact)])->fetch();if(!$x||(int)$x['project_id']!==(int)$r['project_id']||!hash_equals($x['proposal_hash'],hash('sha256',$x['proposal_json'])))crm_fail(422,'Артефакт предложения недоступен.');$proposal=json_decode($x['proposal_json'],true);if(($proposal['quotation']['id']??null)!==(int)$q['id']||($proposal['quotation']['checksum']??null)!==$q['checksum'])crm_fail(409,'Артефакт относится к другой цене.');$text.="\nЧерновик агента для проверки владельцем:\n".$proposal['result']['body'];}
 if(mb_strlen($text)>9000)crm_fail(422,'Предложение слишком велико.');$doc=cc_create_document_effect($a,(int)$r['project_id'],['kind'=>'description','title'=>'Коммерческое предложение №'.$id,'fields'=>['title'=>'Коммерческое предложение №'.$id,'description'=>$text,'requirements'=>$spec['fields']['requirements'],'acceptance'=>'Принятие этого предложения и точной редакции ТЗ не подтверждает выполнение работ.'],'file_ids'=>[]]);
 $body=['request_id'=>$id,'brief_id'=>(int)$b['id'],'brief_hash'=>$b['checksum'],'service_version_id'=>(int)$r['service_version_id'],'package_key'=>$r['package_key'],'quotation_id'=>(int)$q['id'],'quotation_hash'=>$q['checksum'],'price_minor'=>(int)$q['calculation']['selling_minor'],'currency'=>'RUB','spec_revision_id'=>(int)$spec['id'],'spec_checksum'=>$spec['checksum'],'specification'=>array_intersect_key($spec['fields'],array_flip(['title','requirements','acceptance','constraints'])),'proposal_revision_id'=>(int)$doc['id'],'proposal_checksum'=>$doc['revision']['checksum'],'text'=>$text,'terms'=>$terms,'due_on'=>$due,'expires_at'=>$until];$raw=ai_json($body);crm_query("UPDATE nd_catalog_offers SET state='SUPERSEDED',version=version+1 WHERE request_id=? AND state='DRAFT'",[$id]);crm_query('INSERT INTO nd_catalog_offers(request_id,brief_id,quotation_id,proposal_revision_id,body,checksum,quotation_hash,pricing_scope_hash,expires_at,due_on) VALUES (?,?,?,?,?,?,?,?,?,?)',[$id,$b['id'],$q['id'],$doc['id'],$raw,hash('sha256',$raw),$q['checksum'],cat_scope_hash($q['calculation']['scope']),$until,$due]);$oid=(int)db()->lastInsertId();cat_event($a,$r,'offer_draft');return ['ok'=>true,'id'=>$oid];});
}
function cat_publish(int $id,array $d):array{
 return crm_idempotent('catalog:publish-offer:'.$id,$d,function()use($id,$d){$a=['type'=>'owner','id'=>1];$o=cat_record('offer',$id);$r=cat_request($a,(int)$o['request_id'],true);$o=cat_record('offer',$id,true);crm_version($d,$o);if($o['state']!=='DRAFT'||($d['confirm']??false)!==true||($d['checksum']??null)!==$o['checksum'])crm_fail(409,'Подтвердите точное предложение для отправки клиенту.');$q=cat_current_offer($r,$o);cat_live((int)$r['service_version_id']);$body=json_decode($o['body'],true);
 foreach([['id'=>$body['spec_revision_id'],'hash'=>$body['spec_checksum']],['id'=>$body['proposal_revision_id'],'hash'=>$body['proposal_checksum']]] as $ref){$rev=cc_revision($a,(int)$ref['id']);if($rev['checksum']!==$ref['hash'])crm_fail(409,'Документы изменились после подготовки предложения.');$ready=cc_ready_effect($a,(int)$rev['id'],['version'=>(int)$rev['version']]);cc_submit_effect($a,(int)$rev['id'],['version'=>(int)$ready['revision']['version'],'confirm'=>true]);}
 crm_query("UPDATE nd_catalog_offers SET state='AWAITING_ACCEPTANCE',published_by=1,published_at=UTC_TIMESTAMP(),version=version+1 WHERE id=?",[$id]);crm_query("UPDATE nd_catalog_requests SET state='AWAITING_ACCEPTANCE',version=version+1 WHERE id=?",[$r['id']]);cat_transition_scope($o,'PUBLISHED',(int)$r['project_id']);
 $deal=crm_record('deals',(int)$r['deal_id'],true);if($deal['status']==='new'){crm_transition('deals','new','qualified');$deal['status']='qualified';}crm_transition('deals',$deal['status'],'proposal');crm_query("UPDATE nd_deals SET estimated_amount=?,status='proposal',version=version+1 WHERE id=?",[bill_decimal((int)$q['calculation']['selling_minor']),$deal['id']]);crm_event('deals',(int)$deal['id'],'updated',crm_record('deals',(int)$deal['id']));cat_event($a,$r,'offer_published');return ['ok'=>true,'id'=>$id];});
}
function cat_accept(array $a,int $id,array $d):array{
 if($a['type']!=='customer')crm_fail(403,'Предложение принимает клиент.');return crm_idempotent('catalog:accept:'.$a['id'].':'.$id,$d,function()use($a,$id,$d){$o=cat_record('offer',$id);$r=cat_request($a,(int)$o['request_id'],true);$o=cat_record('offer',$id,true);if($o['state']==='ACCEPTED'||$o['state']==='CONFIRMED'){if(($d['checksum']??null)!==$o['accepted_checksum'])crm_fail(409,'Неверная редакция.');return ['ok'=>true,'id'=>$id];}crm_version($d,$o);if($o['state']!=='AWAITING_ACCEPTANCE'||$r['state']!=='AWAITING_ACCEPTANCE'||($d['checksum']??null)!==$o['checksum']||($d['confirm']??false)!==true)crm_fail(409,'Подтвердите актуальное предложение.');cat_live((int)$r['service_version_id']);cat_current_offer($r,$o);$b=cat_brief($r);
 foreach([(int)$b['spec_revision_id'],(int)$o['proposal_revision_id']] as $rid){$rev=cc_revision($a,$rid);cc_decide_effect($a,(int)$rev['approval']['id'],['version'=>(int)$rev['approval']['version'],'checksum'=>$rev['checksum'],'decision'=>'approved','feedback'=>'Принято через точное предложение каталога.','confirm'=>true]);}
 crm_query("UPDATE nd_catalog_offers SET state='ACCEPTED',accepted_account_id=?,accepted_at=UTC_TIMESTAMP(),accepted_checksum=checksum,version=version+1 WHERE id=?",[$a['id'],$id]);crm_query("UPDATE nd_catalog_requests SET state='ACCEPTED',version=version+1 WHERE id=?",[$r['id']]);cat_transition_scope($o,'ACCEPTED',(int)$r['project_id']);cat_event($a,$r,'offer_accepted');return ['ok'=>true,'id'=>$id];});
}
function cat_confirm(array $a,int $id,array $d):array{
 if($a['type']!=='customer')crm_fail(403,'Заказ подтверждает клиент.');return crm_idempotent('catalog:confirm:'.$a['id'].':'.$id,$d,function()use($a,$id,$d){$r=cat_request($a,$id,true);if($r['state']==='CONFIRMED'&&$r['order_id'])return ['ok'=>true,'id'=>$id,'order_id'=>(int)$r['order_id']];crm_version($d,$r);if($r['state']!=='ACCEPTED'||($d['confirm']??false)!==true)crm_fail(409,'Сначала примите одобренное предложение.');$project=cc_project($a,(int)$r['project_id'],true,true);if($project['order_id']!==null)crm_fail(409,'Проект уже связан с заказом владельцем. Нельзя автоматически создать другой заказ; требуется согласование связи в CRM.');$o=crm_query("SELECT * FROM nd_catalog_offers WHERE request_id=? AND state='ACCEPTED' ORDER BY id DESC LIMIT 1 FOR UPDATE",[$id])->fetch();if(!$o)crm_fail(409,'Нет принятой редакции предложения.');$q=cat_current_offer($r,$o);$deal=crm_record('deals',(int)$r['deal_id'],true);crm_transition('deals',$deal['status'],'won');crm_query("UPDATE nd_deals SET status='won',estimated_amount=?,version=version+1 WHERE id=?",[bill_decimal((int)$q['calculation']['selling_minor']),$deal['id']]);$deal=crm_record('deals',(int)$deal['id']);$order=crm_convert_effect((int)$deal['id'],['version'=>(int)$deal['version'],'confirm'=>true],$a)['record'];if($order['status']!=='draft'||(int)$order['customer_id']!==(int)$r['customer_id']||bill_minor($order['total_amount'])!==(int)$q['calculation']['selling_minor'])crm_fail(409,'Существующий заказ требует проверки владельца.');crm_transition('orders','draft','confirmed');crm_query("UPDATE nd_orders SET status='confirmed',due_on=?,version=version+1 WHERE id=?",[$o['due_on'],$order['id']]);crm_query('UPDATE nd_projects SET order_id=?,due_on=?,version=version+1 WHERE id=? AND order_id IS NULL',[$order['id'],$o['due_on'],$r['project_id']]);crm_query("UPDATE nd_catalog_requests SET order_id=?,state='CONFIRMED',version=version+1 WHERE id=?",[$order['id'],$id]);crm_query("UPDATE nd_catalog_offers SET state='CONFIRMED',version=version+1 WHERE id=?",[$o['id']]);cat_transition_scope($o,'CONFIRMED',(int)$r['project_id']);crm_event('deals',(int)$deal['id'],'updated',$deal,$a);crm_event('orders',(int)$order['id'],'updated',crm_record('orders',(int)$order['id']),$a);cat_event($a,$r,'order_confirmed');return ['ok'=>true,'id'=>$id,'order_id'=>(int)$order['id']];});
}
